targetScope = 'resourceGroup'

@description('Location for all resources')
param location string = resourceGroup().location

@description('Short environment name used to build resource names')
param environmentName string = 'dev'

var vmNamePrefix = 'vm-${environmentName}'

resource nic 'Microsoft.Network/networkInterfaces@2024-07-01' = {
  name: '${vmNamePrefix}-nic'
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          privateIPAllocationMethod: 'Dynamic'
        }
      }
    ]
  }
}

resource vm 'Microsoft.Compute/virtualMachines@2024-07-01' = {
  name: '${vmNamePrefix}-01'
  location: location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D2s_v5'
    }
    storageProfile: {
      osDisk: {
        name: 'osdisk'
        createOption: 'FromImage'
        managedDisk: {
          storageAccountType: 'Premium_LRS'
        }
      }
      dataDisks: []
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nic.id
        }
      ]
    }
  }
}

output vmId string = vm.id

@description('Location for the key vault and its secret')
param location string = resourceGroup().location

@description('Name of the key vault')
param vaultName string

resource vault 'Microsoft.KeyVault/vaults@2023-07-01' = {
  name: vaultName
  location: location
  sku: {
    family: 'A'
    name: 'standard'
  }
  properties: {
    tenantId: subscription().tenantId
    enableRbacAuthorization: true
    accessPolicies: []
  }
}

resource apiKey 'Microsoft.KeyVault/vaults/secrets@2023-07-01' = {
  parent: vault
  name: 'api-key'
  properties: {
    value: 'replace-me'
    attributes: {
      enabled: true
    }
  }
}

targetScope = 'subscription'

param location string = 'westeurope'
param appName string = 'contosoapp'

resource newRG 'Microsoft.Resources/resourceGroups@2025-04-01' = {
  name: '${appName}-rg'
  location: location
}

module network 'modules/network.bicep' = {
  params: {
    location: location
  }
}

targetScope = 'resourceGroup'

@description('Size of the virtual machine')
param vmSize string = 'Standard_D2s_v5'

param adminUsername string = 'azureuser'

resource vm 'Microsoft.Compute/virtualMachines@2024-07-01' = {
  name: 'app-vm'
  location: resourceGroup().location
  properties: {
    hardwareProfile: {
      vmSize: vmSize
    }
    osProfile: {
      computerName: 'app-vm'
      adminUsername: adminUsername
      adminPassword: 'Placeholder!2345'
    }
  }
}

output deployedVmSize string = vm.properties.hardwareProfile.vmSize

@description('Number of application servers to create')
param serverCount int = 3

@description('Indexes of the servers that must report telemetry to Log Analytics')
param monitoredIndexes array = [0, 1]

resource vnet 'Microsoft.Network/virtualNetworks@2023-09-01' = {
  name: 'payments-vnet'
  location: resourceGroup().location
  properties: {
    addressSpace: {
      addressPrefixes: ['10.20.0.0/16']
    }
  }
}

resource nic 'Microsoft.Network/networkInterfaces@2023-09-01' = {
  name: 'payments-nic'
  location: resourceGroup().location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          subnet: {
            id: vnet.id
          }
        }
      }
    ]
  }
}

resource vm 'Microsoft.Compute/virtualMachines@2024-07-01' = [for i in range(0, serverCount): {
  name: 'payments-vm-${i}'
  location: resourceGroup().location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D4s_v5'
    }
    storageProfile: {
      imageReference: {
        publisher: 'MicrosoftWindowsServer'
        offer: 'WindowsServer'
        sku: '2022-datacenter-azure-edition'
        version: 'latest'
      }
    }
    osProfile: {
      computerName: 'payments-vm-${i}'
      adminUsername: 'azadmin'
      adminPassword: 'Password1234!'
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nic.id
        }
      ]
    }
  }
}]

param vmNames array = [
  'app-vm01'
  'app-vm02'
  'app-vm03'
  'app-vm04'
  'app-vm05'
  'app-vm06'
]

resource vnet 'Microsoft.Network/virtualNetworks@2025-01-01' = {
  name: 'app-vnet'
  location: resourceGroup().location
  properties: {
    addressSpace: {
      addressPrefixes: ['10.0.0.0/16']
    }
    subnets: [
      {
        name: 'snet-app'
        properties: {
          addressPrefix: '10.0.1.0/24'
        }
      }
    ]
  }
}

resource nics 'Microsoft.Network/networkInterfaces@2025-01-01' = [for (name, i) in vmNames: {
  name: '${name}-nic'
  location: resourceGroup().location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          subnet: {
            id: vnet.properties.subnets[0].id
          }
          privateIPAllocationMethod: 'Dynamic'
        }
      }
    ]
  }
}]

resource vms 'Microsoft.Compute/virtualMachines@2025-04-01' = [for (name, i) in vmNames: {
  name: name
  location: resourceGroup().location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D2s_v5'
    }
    osProfile: {
      computerName: name
      adminUsername: 'azureuser'
      adminPassword: 'Placeholder-Pa55word!'
      linuxConfiguration: {
        disablePasswordAuthentication: false
      }
    }
    storageProfile: {
      imageReference: {
        publisher: 'Canonical'
        offer: '0001-com-ubuntu-server-jammy'
        sku: '22_04-lts-gen2'
        version: 'latest'
      }
    }
    networkProfile: {
      networkInterfaces: [
        {
          id: nics[i].id
        }
      ]
    }
  }
}]

output vmIds array = [for (name, i) in vmNames: {
  name: name
  id: vms[i].id
}]

var nameFragment = 'prod'

param storageAccountName string = 'stgapp${nameFragment}'

resource stg 'Microsoft.Storage/storageAccounts@2025-06-01' = {
  name: storageAccountName
  location: resourceGroup().location
  sku: { name: 'Standard_LRS' }
  kind: 'StorageV2'
}

resource logs 'Microsoft.Storage/storageAccounts/blobServices/containers@2025-06-01' = {
  name: '${storageAccountName}/logs'
  properties: {}
}

targetScope = 'resourceGroup'

param vmName string = 'app-vm01'
param location string = resourceGroup().location
param adminUser string = 'azureuser'
param createDataDisk bool = true

var description = 'Finance workload host'

module agent './modules/agent.bicep' = {
  name: 'agentDeploy'
  params: {
    vmName: vmName
  }
}

resource nic 'Microsoft.Network/networkInterfaces@2025-06-01' = {
  name: '${vmName}-nic'
  location: location
  properties: {
    ipConfigurations: [
      {
        name: 'ipconfig1'
        properties: {
          privateIPAllocationMethod: 'Dynamic'
        }
      }
    ]
  }
}

resource vm 'Microsoft.Compute/virtualMachines@2025-06-01' = {
  name: vmName
  location: location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D4s_v5'
    }
    osProfile: {
      computerName: vmName
      adminUsername: adminUser
      adminPassword: 'Temp1234!'
    }
    networkProfile: {
      networkInterfaces: [
        { id: nic.id }
      ]
    }
  }
}

resource dataDisk 'Microsoft.Compute/disks@2025-06-01' = {
  name: '${vmName}-data'
  location: location
  sku: {
    name: 'Premium_LRS'
  }
  properties: {
    diskSizeGB: 128
  }
}

output vmId string = vm.id

targetScope = 'resourceGroup'

param clusterName string = 'app-aks'
param dnsPrefix string = 'app'
param nodeSizes array = [ 'Standard_D4as_v5' ]

resource aks 'Microsoft.ContainerService/managedClusters@2024-05-01' = {
  name: clusterName
  location: resourceGroup().location
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    dnsPrefix: dnsPrefix
    agentPoolProfiles: [
      {
        name: 'systempool'
        count: 3
        vmSize: nodeSizes[0]
        mode: 'System'
        osType: 'Linux'
      }
    ]
    linuxProfile: {
      adminUsername: 'azureuser'
      ssh: {
        keyData: 'ssh-rsa AAAA...'
      }
    }
  }
}

module ingressModule './ingress.bicep' = {
  name: 'app-ingress'
  params: {
    clusterName: clusterName
  }
}

