param adminLogin string = 'azureuser'
param diskNames array = []
param diskSizeGB int = 128

resource vm 'Microsoft.Compute/virtualMachines@2024-07-01' = {
  name: 'app-vm01'
  location: resourceGroup().location
  properties: {
    hardwareProfile: {
      vmSize: 'Standard_D4s_v5'
    }
    storageProfile: {
      imageReference: {
        publisher: 'Canonical'
        offer: '0001-com-ubuntu-server-jammy'
        sku: '22_04-lts-gen2'
        version: 'latest'
      }
      osProfile: {
        computerName: 'app-vm01'
        adminUsername: adminLogin
        linuxConfiguration: {
          disablePasswordAuthentication: true
        }
      }
      dataDisks: [
        for diskName in diskNames: {
          name: diskName
          diskSizeGB: diskSizeGB
          createOption: 'Empty'
          lun: 0
        }
      ]
    }
  }
}

param adminName string = 'azureuser'
param adminPassword string
param tags object = {}
param shareNames array = [ 'logs', 'backups' ]

