}

resource storageAcct 'Microsoft.Storage/storageAccounts@2025-06-01' = {
  name: 'appstoracct'
  location: location
  kind: 'StorageV2'
  sku: { name: 'Standard_LRS' }
}

output vmId string = vm.id

