}

targetScope = 'resourceGroup'

@description('Resource group that holds the shared data services')
param sharedRgName string = 'rg-shared-data'

@description('Blob endpoint the application writes to')
param dataEndpoint string = reference(resourceId('Microsoft.Storage/storageAccounts', sharedRgName, 'stshared01'), '2023-05-01').primaryEndpoints.blob

resource stg 'Microsoft.Storage/storageAccounts@2025-06-01' = {
  name: 'stappdata01'
  location: resourceGroup().location
  sku: {
    name: 'Standard_LRS'
  }
  kind: 'StorageV2'
}

module reports './modules/reports/main.bicep' = {
  name: 'reportsDeploy'
}

module audit './modules/audit/main.bicep' = {
  name: 'reportsDeploy'
}

output blobEndpoint string = dataEndpoint

param monitoringEnabled bool = true
param opsRgName string

resource vm 'Microsoft.Compute/virtualMachines@2025-06-01' existing = {
  name: 'app-vm'
}

module agentModule './modules/monitoringAgent.bicep' = {
  name: 'monitoringDeploy'
  params: {
    virtualMachineName: vm.name
  }
}

// Bicep CLI on the build agent: 0.36.2
param vaultName string
param adminLogin string

module dbModule '../modules/sql-server.bicep' = {
  name: 'dbDeploy'
  params: {
    administratorLogin: adminLogin
    keyVaultName: vaultName
  }
}

resource vault 'Microsoft.KeyVault/vaults@2023-07-01' = {
  name: vaultName
  location: resourceGroup().location
  properties: {
    sku: {
      family: 'A'
      name: 'standard'
    }
    tenantId: subscription().tenantId
    enableRbacAuthorization: true
  }
}

resource dbAdminSecret 'Microsoft.KeyVault/vaults/secrets@2023-07-01' = {
  parent: vault
  name: 'sql-admin-password'
  properties: {
    value: dbModule.outputs.adminPassword
  }
}

param location string = resourceGroup().location
param storageAccountName string = 'stappdata001'
param blobEndpoint string = reference(stg.id).primaryEndpoints.blob

resource stg 'Microsoft.Storage/storageAccounts@2025-06-01' = {
  name: storageAccountName
  location: location
  sku: {
    name: 'Standard_LRS'
  }
  kind: 'StorageV2'
}

module monitoring '.\modules\monitoring.bicep' = {
  name: 'monitoringDeploy'
  params: {
    targetResourceId: stg.id
  }
}

// excerpt: parameter and network security group sections

@description('Port the application firewall rule opens for the database tier')
@secure()
param dbPort int

var nsgName = 'app-nsg-${uniqueString(resourceGroup().id)}'

resource nsg 'Microsoft.Network/networkSecurityGroups@2024-05-01' = {
  name: nsgName
  location: resourceGroup().location
  properties: {
    securityRules: [
      {
        name: 'allow-db-tier'
        properties: {
          priority: 100
          direction: 'Inbound'
          access: 'Allow'
          protocol: 'Tcp'
          sourceAddressPrefix: '10.0.0.0/8'
          destinationPortRange: string(dbPort)
        }
      }
    ]
  }
}

param subnetNames array = []
param addressPrefix string = '10.20.0.0/16'

resource vnet 'Microsoft.Network/virtualNetworks@2024-05-01' = {
  name: 'platform-vnet'
  location: resourceGroup().location
  properties: {
    addressSpace: {
      addressPrefixes: [
        addressPrefix
      ]
    }
    subnets: [
      for sn in subnetNames: {
        name: sn
        properties: {
          addressPrefix: addressPrefix
        }
      }
    ]
  }
}
